package bowling

import "errors"

// Game keeps track of a game of bowling.
type Game struct {
	rolls        []int // every roll, in order
	frame        int   // 0-9, the frame currently being played
	rollInFrame  int   // 0, 1 (or 2 in the tenth frame)
	pinsStanding int   // pins still standing for the next roll
	gameOver     bool
}

// NewGame returns a new, empty bowling game.
func NewGame() *Game {
	return &Game{
		pinsStanding: 10,
	}
}

// Roll records a ball that knocked down pins. It returns an error if the
// roll is illegal (negative, too many pins, or the game is already over).
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errors.New("Negative roll is invalid")
	}
	if g.gameOver {
		return errors.New("Cannot roll after game is over")
	}
	if pins > g.pinsStanding {
		return errors.New("Pin count exceeds pins on the lane")
	}
	g.rolls = append(g.rolls, pins)
	g.advance()
	return nil
}

// advance moves the game state forward after a legal roll.
func (g *Game) advance() {
	last := g.rolls[len(g.rolls)-1]
	if g.frame < 9 {
		// Frames 1-9: a strike ends the frame, otherwise a second roll.
		if g.rollInFrame == 0 {
			if last == 10 {
				g.frame++
				g.rollInFrame = 0
				g.pinsStanding = 10
			} else {
				g.rollInFrame = 1
				g.pinsStanding = 10 - last
			}
		} else {
			g.frame++
			g.rollInFrame = 0
			g.pinsStanding = 10
		}
		return
	}

	// Tenth frame: a strike earns two fill balls, a spare earns one.
	switch g.rollInFrame {
	case 0:
		g.rollInFrame = 1
		if last == 10 {
			g.pinsStanding = 10
		} else {
			g.pinsStanding = 10 - last
		}
	case 1:
		first := g.rolls[len(g.rolls)-2]
		switch {
		case first == 10:
			// First ball was a strike; this was the first fill ball.
			g.rollInFrame = 2
			if last == 10 {
				g.pinsStanding = 10
			} else {
				g.pinsStanding = 10 - last
			}
		case first+last == 10:
			// Spare; one fill ball remains.
			g.rollInFrame = 2
			g.pinsStanding = 10
		default:
			// Open frame; the game is over.
			g.rollInFrame = 3
			g.pinsStanding = 0
			g.gameOver = true
		}
	case 2:
		// Final fill ball rolled; the game is over.
		g.rollInFrame = 3
		g.pinsStanding = 0
		g.gameOver = true
	}
}

// Score returns the total score of the game. It returns an error if the game
// is not yet complete.
func (g *Game) Score() (int, error) {
	if !g.gameOver {
		return 0, errors.New("Score cannot be taken until the end of the game")
	}
	score := 0
	i := 0
	for frame := 0; frame < 9; frame++ {
		switch {
		case g.rolls[i] == 10:
			// Strike: 10 plus the next two rolls.
			score += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		case g.rolls[i]+g.rolls[i+1] == 10:
			// Spare: 10 plus the next roll.
			score += 10 + g.rolls[i+2]
			i += 2
		default:
			// Open frame.
			score += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	// Tenth frame: the total is simply the sum of its rolls.
	for ; i < len(g.rolls); i++ {
		score += g.rolls[i]
	}
	return score, nil
}
